<script setup>import {ref} from 'vue';import {post} from '../api/client';const emit=defineEmits(['completed']),current=ref(''),next=ref(''),confirm=ref(''),message=ref('');async function save(){if(next.value!==confirm.value){message.value='两次输入的新密码不一致';return}try{await post('/auth/change-password',{current_password:current.value,new_password:next.value});message.value='密码修改成功';emit('completed')}catch(e){message.value=e.message}}</script>
<template><div class="auth-page"><form class="auth-card card" @submit.prevent="save"><h1>首次登录修改密码</h1><p class="hint">密码至少10位，并同时包含字母和数字。</p><label>当前密码<input v-model="current" type="password"></label><label>新密码<input v-model="next" type="password"></label><label>确认新密码<input v-model="confirm" type="password"></label><p v-if="message" class="notice">{{message}}</p><button>保存新密码</button></form></div></template>
